//! Demo: renders kitty-pptx Reader frames for a mixed-orientation PDF and
//! composites them into terminal-screenshot PNGs (one per row turn, plus a
//! continuous j-scroll glide through the first orientation change).
//!
//! Usage (the committed fixture mixes letter portrait pages with /Rotate 90
//! figures, native landscape pages, and a landscape page rotated back to
//! portrait):
//!   cargo run -p kitty-pptx-cli --example mixed_orientation_demo -- \
//!       crates/kitty-pptx-pdf/tests/fixtures/mixed_orientation.pdf /tmp/mixed_demo 160 45
//!
//! The fixture itself is generated by
//! `crates/kitty-pptx-pdf/tests/fixtures/gen_mixed_orientation.py`.
//!
//! Prints the per-page box/rotation/display table, the auto mode decision,
//! each frame's status line, and writes frame_<anchor>.png per row.

use std::collections::HashMap;
use std::sync::Arc;

use crossterm::event::{KeyCode, KeyEvent, KeyEventKind, KeyEventState, KeyModifiers};
use image::RgbaImage;
use kitty_pptx_core::RgbaSlide;
use kitty_pptx_display::probe_cell_pixel_size;
use kitty_pptx_pdf::{classify_mode, HayroEngine, PdfEngine};
use kitty_pptx_tui::app::bindings::FrameBindings;
use kitty_pptx_tui::app::events::handle_key_event;
use kitty_pptx_tui::app::state::PresentationState;
use kitty_pptx_tui::app::ui::render_reader;
use ratatui::backend::TestBackend;
use ratatui::layout::Rect;
use ratatui::Terminal;

fn make_key(code: KeyCode) -> KeyEvent {
    KeyEvent {
        code,
        modifiers: KeyModifiers::NONE,
        kind: KeyEventKind::Press,
        state: KeyEventState::NONE,
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let pdf_path = args.next().unwrap_or_else(|| "/tmp/mixed_orientation.pdf".into());
    let out_dir = args.next().unwrap_or_else(|| "/tmp/mixed_demo".into());
    let cols: u16 = args.next().and_then(|a| a.parse().ok()).unwrap_or(160);
    let rows: u16 = args.next().and_then(|a| a.parse().ok()).unwrap_or(45);
    let _ = std::fs::create_dir_all(&out_dir);

    let bytes: Arc<[u8]> = std::fs::read(&pdf_path).expect("read pdf").into();
    let engine = HayroEngine::open(Arc::clone(&bytes)).expect("open pdf");
    let total = engine.page_count();

    // ── Per-page orientation table ─────────────────────────────────────────
    let mut page_sizes = Vec::with_capacity(total);
    println!("page | box/rot       | displays  | page_size_pt");
    println!("-----+---------------+----------+-------------");
    for i in 0..total {
        let (w, h) = engine.page_size_pt(i);
        let rot = engine.page_rotation(i);
        let disp = if w > h { "LANDSCAPE" } else { "PORTRAIT " };
        println!(" {i:>4} | rot {rot:>3}       | {disp}  | {w:.0} x {h:.0} pt");
        page_sizes.push((w, h));
    }
    match classify_mode(&page_sizes) {
        Ok(decision) => println!("\nauto mode decision: {decision:?}"),
        Err(e) => println!("\nauto mode decision failed: {e}"),
    }

    // ── Reader state at the demo terminal size ────────────────────────────
    let mut state = PresentationState::new(total, vec![None; total]);
    state.enable_reader_mode(total, page_sizes.clone());
    state.set_layout_dimensions(cols, rows);

    let metrics = probe_cell_pixel_size();
    let cell_w = metrics.width_px.max(4.0) as u32;
    let cell_h = metrics.height_px.max(8.0) as u32;
    let canvas_w = cols as u32 * cell_w;
    let canvas_h = rows as u32 * cell_h;
    println!(
        "\nterminal {cols}x{rows} cells, cell {cell_w}x{cell_h}px, canvas {canvas_w}x{canvas_h}px"
    );

    // Raster cache: (page, target width) -> rendered slide.
    let mut cache: HashMap<(usize, u32), RgbaSlide> = HashMap::new();
    let mut terminal = Terminal::new(TestBackend::new(cols, rows)).unwrap();

    let mut anchor;
    for frame in 0..10 {
        // Draw one reader frame and capture the placements the renderer
        // actually computed (exactly what the run loop publishes).
        let mut bindings = FrameBindings::default();
        terminal
            .draw(|f| render_reader(&state, f, Rect::new(0, 0, cols, rows), &mut bindings))
            .unwrap();
        state.publish_frame_bindings(bindings.clone());

        let placements = &bindings.reader;
        if placements.is_empty() {
            break;
        }
        anchor = placements[0].page;

        let status = state
            .reader_state()
            .unwrap()
            .status_line("mixed_orientation.pdf", placements, bindings.reader_columns);
        println!(
            "\nframe {frame}: anchor page {anchor} (0-based), {} panes, columns {}",
            placements.len(),
            bindings.reader_columns
        );
        println!("  status: {status}");
        for p in placements {
            println!(
                "  page {:>2} -> cells col {}..{} row {}..{} | src {}x{} of target {}x{}",
                p.page,
                p.cell_rect.col,
                p.cell_rect.col + p.cell_rect.cols,
                p.cell_rect.row,
                p.cell_rect.row + p.cell_rect.rows,
                p.pixel_src.width,
                p.pixel_src.height,
                p.page_target.width_px,
                p.page_target.height_px
            );
        }

        // ── Composite the frame into a PNG "screenshot" ────────────────────
        let mut canvas = RgbaImage::from_pixel(canvas_w, canvas_h, image::Rgba([20, 23, 33, 255]));
        for p in placements {
            let key = (p.page, p.page_target.width_px);
            let slide = match cache.get(&key) {
                Some(s) => s.clone(),
                None => {
                    let s = engine.render_raster(p.page, &p.page_target).expect("render page");
                    cache.insert(key, s.clone());
                    s
                }
            };
            blit_placement(&mut canvas, &slide, p, cell_w, cell_h);
        }
        let out = format!("{out_dir}/frame_{frame:02}_anchor{anchor:02}.png");
        canvas.save(&out).unwrap();
        println!("  wrote {out}");

        // Row turn: PageDown advances by the frame's published column count.
        handle_key_event(make_key(KeyCode::PageDown), &mut state);
        let next_anchor = state.reader_state().unwrap().anchor;
        if next_anchor == anchor {
            break;
        }
    }

    // ── Continuous scroll through the first orientation change ────────────
    // Press j (1/8 of the row stride) from the top of the document and save
    // every frame: the row [1,2] glides up, the [3,4] row peeks in from
    // below at the same columns, and the anchor flip is invisible.
    let mut state = PresentationState::new(total, vec![None; total]);
    state.enable_reader_mode(total, page_sizes.clone());
    state.set_layout_dimensions(cols, rows);
    let mut terminal = Terminal::new(TestBackend::new(cols, rows)).unwrap();
    println!("\nglide: continuous j-scroll across the row 1-2 / row 3-4 boundary");
    for step in 0..16 {
        let mut bindings = FrameBindings::default();
        terminal
            .draw(|f| render_reader(&state, f, Rect::new(0, 0, cols, rows), &mut bindings))
            .unwrap();
        state.publish_frame_bindings(bindings.clone());

        let placements = &bindings.reader;
        if !placements.is_empty() {
            let cols_line: Vec<String> = placements
                .iter()
                .map(|p| {
                    format!(
                        "p{}@c{}..{}r{}..{}",
                        p.page + 1,
                        p.cell_rect.col,
                        p.cell_rect.col + p.cell_rect.cols,
                        p.cell_rect.row,
                        p.cell_rect.row + p.cell_rect.rows
                    )
                })
                .collect();
            println!("  step {step:>2}: {}", cols_line.join("  "));
            let mut canvas =
                RgbaImage::from_pixel(canvas_w, canvas_h, image::Rgba([20, 23, 33, 255]));
            for p in placements {
                let key = (p.page, p.page_target.width_px);
                let slide = match cache.get(&key) {
                    Some(s) => s.clone(),
                    None => {
                        let s =
                            engine.render_raster(p.page, &p.page_target).expect("render page");
                        cache.insert(key, s.clone());
                        s
                    }
                };
                blit_placement(&mut canvas, &slide, p, cell_w, cell_h);
            }
            let out = format!("{out_dir}/glide_{step:02}.png");
            canvas.save(&out).unwrap();
        }
        handle_key_event(make_key(KeyCode::Char('j')), &mut state);
        while state.reader_state().unwrap().advance_display() {}
    }
    println!("\ndone");
}

/// Crops `slide` to the placement's source window (raster pixels, clamped to
/// the actual raster) and bilinearly scales it into the placement's cell box
/// on the canvas — the same mapping the Kitty driver performs on placement.
fn blit_placement(
    canvas: &mut RgbaImage,
    slide: &RgbaSlide,
    p: &kitty_pptx_tui::app::reader_types::ReaderSlotPlacement,
    cell_w: u32,
    cell_h: u32,
) {
    let raster_w = slide.width;
    let raster_h = slide.height;
    let src_x = p.pixel_src.x.min(raster_w.saturating_sub(1));
    let src_y = p.pixel_src.y.min(raster_h.saturating_sub(1));
    let src_w = p.pixel_src.width.min(raster_w - src_x).max(1);
    let src_h = p.pixel_src.height.min(raster_h - src_y).max(1);

    let dst_x = p.cell_rect.col as u32 * cell_w;
    let dst_y = p.cell_rect.row as u32 * cell_h;
    let dst_w = p.cell_rect.cols as u32 * cell_w;
    let dst_h = p.cell_rect.rows as u32 * cell_h;

    let px = &slide.pixels;
    let sample = |x: u32, y: u32| -> [u8; 4] {
        let idx = ((y as usize * raster_w as usize) + x as usize) * 4;
        [px[idx], px[idx + 1], px[idx + 2], 255]
    };

    for dy in 0..dst_h {
        let fy = src_y as f32 + (dy as f32 / dst_h.max(1) as f32) * (src_h.saturating_sub(1)) as f32;
        let y0 = fy.floor() as u32;
        let y1 = (y0 + 1).min(src_y + src_h - 1);
        let ty = fy - y0 as f32;
        for dx in 0..dst_w {
            let fx =
                src_x as f32 + (dx as f32 / dst_w.max(1) as f32) * (src_w.saturating_sub(1)) as f32;
            let x0 = fx.floor() as u32;
            let x1 = (x0 + 1).min(src_x + src_w - 1);
            let tx = fx - x0 as f32;

            let c00 = sample(x0, y0);
            let c10 = sample(x1, y0);
            let c01 = sample(x0, y1);
            let c11 = sample(x1, y1);
            let mix = |a: u8, b: u8, t: f32| -> u8 {
                (a as f32 * (1.0 - t) + b as f32 * t).round().clamp(0.0, 255.0) as u8
            };
            let top = [
                mix(c00[0], c10[0], tx),
                mix(c00[1], c10[1], tx),
                mix(c00[2], c10[2], tx),
                255,
            ];
            let bot = [
                mix(c01[0], c11[0], tx),
                mix(c01[1], c11[1], tx),
                mix(c01[2], c11[2], tx),
                255,
            ];
            let out = [
                mix(top[0], bot[0], ty),
                mix(top[1], bot[1], ty),
                mix(top[2], bot[2], ty),
                255,
            ];
            canvas.put_pixel(dst_x + dx, dst_y + dy, image::Rgba(out));
        }
    }
}
